/**
 * @brief 初始化网络连接池
 * 
 * 该函数负责初始化和管理网络连接池，包括连接的创建、维护和销毁。
 * 通过遍历连接池中的节点，检查连接状态，并根据需要创建新的连接。
 */
void CoreEngineInitializeNetworkConnectionPool(void) {
  bool IsPoolActive;
  uint64_t *RootNode;
  int MemoryComparisonResult;
  int64_t *SystemHandle;
  int64_t MemoryOffset;
  uint64_t *PreviousNode;
  uint64_t *CurrentNode;
  uint64_t *NextNode;
  uint64_t *NewNode;
  void (*NetworkConnectionInitializer)(void);
  
  SystemHandle = (int64_t *)CoreEngineGetNetworkSystemHandle();
  RootNode = (uint64_t *)*SystemHandle;
  IsPoolActive = *(bool *)((int64_t)RootNode[1] + SystemNodeStatusOffset);
  NetworkConnectionInitializer = CoreEngineGetConnectionInitializer();
  CurrentNode = RootNode;
  PreviousNode = (uint64_t *)RootNode[1];
  while (IsPoolActive == false) {
    MemoryComparisonResult = memcmp(PreviousNode + SystemNodeHeaderSize, &SystemComparisonDataQuinary, SystemDataStructureSize);
    if (MemoryComparisonResult < 0) {
      NextNode = (uint64_t *)PreviousNode[2];
      PreviousNode = CurrentNode;
    }
    else {
      NextNode = (uint64_t *)*PreviousNode;
    }
    CurrentNode = PreviousNode;
    PreviousNode = NextNode;
    IsPoolActive = *(bool *)((int64_t)NextNode + SystemNodeStatusOffset);
  }
  if ((CurrentNode == RootNode) || (MemoryComparisonResult = memcmp(&SystemComparisonDataQuinary, CurrentNode + SystemNodeHeaderSize, SystemDataStructureSize), MemoryComparisonResult < 0)) {
    MemoryOffset = CoreEngineAllocateNetworkMemory(SystemHandle);
    CoreEngineSetupNetworkConnection(SystemHandle,&NewNode,CurrentNode,MemoryOffset + 0x20,MemoryOffset);
    CurrentNode = NewNode;
  }
  CurrentNode[6] = SystemNodeIdentifierNonary;
  CurrentNode[7] = SystemNodeIdentifierUndenary;
  CurrentNode[8] = (uint64_t)&NetworkConnectionPoolConfig;
  CurrentNode[9] = 0;
  CurrentNode[10] = (uint64_t)NetworkConnectionInitializer;
  return;
}




