      if (blockSize != 0) {
                    // WARNING: Subroutine does not return
        memcpy(*(void *)(CharacterCode + (long long)bufferStatusPointer),*bufferStatusPointer,dataSize);
      }
      *(uint32_t *)(CharacterCode + 8 + (long long)bufferStatusPointer) = 0;
      if (*(long long *)(CharacterCode + (long long)bufferStatusPointer) != 0) {
        *(uint8_t *)(dataSize + *(long long *)(CharacterCode + (long long)bufferStatusPointer)) = 0;
      }
      blockCount = blockCount + -1;
      *(uint32_t *)(CharacterCode + 0x14 + (long long)bufferStatusPointer) = *(uint32_t *)((long long)bufferStatusPointer + 0x14);
      Utf8SourcePointer = Utf8SourcePointer + 0x20;
      bufferStatusPointer = bufferStatusPointer + 4;
